    "enabled": true,
    "model": "BAAI/bge-reranker-large",
    "score_threshold": 0.65,
    "final_top_n": 4
  },
  "prompt_guardrails": {
    "strict_context_only": true,
    "fallback_message": "在当前提供的企业知识库范围内未检索到确切依据，请提供更多线索或联系人工处理。"
